class Solution { public: vector<int> getOrder(vector<vector<int>>& tasks){vector<array<int,3>> indexed;for(int i=0;i<(int)tasks.size();++i)indexed.push_back({tasks[i][0],tasks[i][1],i});sort(indexed.begin(),indexed.end());priority_queue<pair<int,int>,vector<pair<int,int>>,greater<pair<int,int>>> ready;vector<int> answer;int next=0;long long time=0;while(answer.size()<tasks.size()){if(ready.empty())time=max(time,1LL*indexed[next][0]);while(next<(int)tasks.size()&&indexed[next][0]<=time){ready.push({indexed[next][1],indexed[next][2]});++next;}auto [duration,index]=ready.top();ready.pop();answer.push_back(index);time+=duration;}return answer;} };
